package com.hartens.optimizer;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.concurrent.*;
public final class MainActivity extends Activity{
 private EditText ip;private TextView result;private LinearLayout root;private ExecutorService worker=Executors.newSingleThreadExecutor();private SharedPreferences prefs;
 interface Task{String run(Optimizer o)throws Exception;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("optimizer",0);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101525);root.setPadding(22,24,22,24);sc.addView(root);setContentView(sc);
 title("⚡ HARTENS OPTIMIZER 2.0");label("Для Hartens HTY-43F06B-VZ • Android 11\nТелефон и ТВ в одной Wi-Fi сети. Отключи VPN. Это тестовая версия.");ip=new EditText(this);ip.setTextColor(Color.WHITE);ip.setHintTextColor(0xff9aa4b5);ip.setHint("IP телевизора");ip.setSingleLine(true);ip.setInputType(2|8192);ip.setText(prefs.getString("ip","192.168.1.38"));root.addView(ip);
 section("ПОДКЛЮЧЕНИЕ");button("🔍 Полная диагностика",o->o.diagnostics());button("📋 Статус компонентов",o->o.status());
 section("ОПТИМИЗАЦИЯ");button("🚀 ТУРБО: безопасный профиль",o->o.quick());label("Ускоряет анимации до 0.25x, отключает только Яндекс Игры и отчёты об ошибках, запрашивает очистку кэша. Реальный прирост зависит от телевизора.");button("⚡ Умеренный режим 0.5x",o->o.animations("0.5"));button("⚡ Быстрый режим 0.25x",o->o.animations("0.25"));button("🧹 Очистить кэш и сравнить место",o->o.cleanCache());
 section("ВЫБОРОЧНО");button("🎮 Отключить Яндекс Игры",o->o.disable(Optimizer.GAMES));button("🐞 Отключить отчёты об ошибках",o->o.disable(Optimizer.BUGS));button("🛡️ Отключить рекламный ID (экспериментально)",o->o.disable(Optimizer.ADID));label("Рекламный ID не равен рекламным баннерам: отключение может повлиять на сервисы Яндекса. Не гарантирует блокировку рекламы.");
 section("ВОССТАНОВЛЕНИЕ");button("↩ Восстановить изменения приложения",o->o.restore());button("↩ Восстановить Яндекс Игры*",o->o.restoreOne(Optimizer.GAMES));button("↩ Восстановить отчёты об ошибках*",o->o.restoreOne(Optimizer.BUGS));label("* Только если отключены этим приложением. Изменения, выполненные ранее через Termux, не перезаписываются.");
 section("РЕЗУЛЬТАТ");result=new TextView(this);result.setTextColor(Color.WHITE);result.setTextSize(15);result.setTextIsSelectable(true);result.setPadding(18,24,18,30);result.setText("Начни с диагностики. Перед изменениями проверь работу Bluetooth и Алисы.");root.addView(result);label("Системные пакеты Bluetooth, Алиса, лаунчер YaOS, звук, Wi-Fi и пульт не отключаются. После использования отключай ADB Mode на ТВ.");}
 private void title(String t){TextView v=new TextView(this);v.setText(t);v.setTextSize(24);v.setTextColor(0xff99b8ff);v.setPadding(0,8,0,16);root.addView(v);}
 private void section(String t){TextView v=new TextView(this);v.setText(t);v.setTextSize(18);v.setTextColor(0xffb5caff);v.setPadding(0,26,0,9);root.addView(v);}
 private void label(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(14);v.setTextColor(0xffd2d8e4);v.setPadding(0,5,0,10);root.addView(v);}
 private void button(String name,Task task){Button b=new Button(this);b.setAllCaps(false);b.setText(name);root.addView(b);b.setOnClickListener(view->new AlertDialog.Builder(this).setTitle(name).setMessage("Выполнить на Hartens?").setNegativeButton("Отмена",null).setPositiveButton("Да",(d,w)->execute(task)).show());}
 private void execute(Task task){String host=ip.getText().toString().trim();prefs.edit().putString("ip",host).apply();result.setText("Подключение к ТВ...");worker.execute(()->{String s;try(AdbClient a=new AdbClient(this)){a.connect(host);s=task.run(new Optimizer(a,prefs,host));}catch(Exception e){s="ОШИБКА: "+e.getMessage()+"\nПроверь адрес, отключи VPN, подтверди ADB на ТВ."; }final String out=s;runOnUiThread(()->result.setText(out));});}
 protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
